	private static final AtomicInteger XSD_NAMESPACE_PROBES = new AtomicInteger();

	/**
	 * On 6.1.0's store the XSD namespace is absent. The first datatype's alternative-split search publishes that
	 * absence for the pass's snapshot, and it answers the namespace of the next 46 datatypes without another dictionary
	 * probe.
	 */
	@Test
	void anAbsentNamespaceIsProbedOncePerSeedingPass() throws Exception {
		Path store = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", store);
		byte[] namespaceRecord = ("\u0004" + XSD).getBytes(StandardCharsets.UTF_8);
		XSD_NAMESPACE_PROBES.set(0);
		LmdbStore lmdbStore = new LmdbStore(store.toFile(), config()) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig options,
					boolean sketchEnabled) throws IOException {
				LmdbSailStore.ValueStoreFactory values = (path, stored, settings) -> new ValueStore(path, stored,
						settings, false, null, LmdbStoreFormat.fromProperties(stored, settings), true) {
					@Override
					Long findIdInTransaction(byte[] data, boolean create, CoreDatatype coreDatatype, MemoryStack stack,
							long txn) throws IOException {
						if (Arrays.equals(data, namespaceRecord)) {
							XSD_NAMESPACE_PROBES.incrementAndGet();
						}
						return super.findIdInTransaction(data, create, coreDatatype, stack, txn);
					}
				};
				return new LmdbSailStore(dataDir, properties, options, sketchEnabled, values, TripleStore::new);
			}
		};
		SailRepository repository = new SailRepository(lmdbStore);
		int probesWhileOpening;
		try {
			repository.init();
			probesWhileOpening = XSD_NAMESPACE_PROBES.get();
			assertEquals(LmdbValue.UNKNOWN_ID,
					lmdbStore.getBackingStore().valueStore().getId(VF.createIRI(XSD + "integer")),
					"fixture: the XSD namespace and its datatypes are absent");
		} finally {
			repository.shutDown();
		}
		assertEquals(1, probesWhileOpening,
				"the first lookup's published namespace absence serves the rest of the seeding pass");
	}

