	private static final AtomicInteger CREATING_LOOKUPS = new AtomicInteger();

	/**
	 * Exact reference counts make seeding create the missing datatypes, and it creates them all in the startup write
	 * transaction, outside the lookup-only pass: a failure while creating them commits none of them.
	 */
	@Test
	void aFailureWhileCreatingTheMissingDatatypesCommitsNoneOfThem() throws Exception {
		LmdbStoreConfig exact = config().setLegacyReferenceCountRepairEnabled(true);
		Path store = legacyStoreWithTrustedCounts(exact);
		Map<String, List<StoredIri>> before = storedIris(store);
		CREATING_LOOKUPS.set(0);
		LmdbStore lmdbStore = new LmdbStore(store.toFile(), exact) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig options,
					boolean sketchEnabled) throws IOException {
				LmdbSailStore.ValueStoreFactory values = (path, stored, settings) -> new ValueStore(path, stored,
						settings, false, null, LmdbStoreFormat.fromProperties(stored, settings), true) {
					@Override
					Long findIdInTransaction(byte[] data, boolean create, CoreDatatype coreDatatype, MemoryStack stack,
							long txn) throws IOException {
						// The XSD namespace and the first missing datatype are created first.
						if (create && CREATING_LOOKUPS.incrementAndGet() == 3) {
							throw new IOException("injected failure of the third creating lookup");
						}
						return super.findIdInTransaction(data, create, coreDatatype, stack, txn);
					}
				};
				return new LmdbSailStore(dataDir, properties, options, sketchEnabled, values, TripleStore::new);
			}
		};
		SailRepository repository = new SailRepository(lmdbStore);
		try {
			Exception failure = assertThrows(Exception.class, repository::init);
			assertTrue(causes(failure, "injected failure of the third creating lookup"),
					() -> "the injected seeding failure fails the open: " + failure);
		} finally {
			repository.shutDown();
		}
		assertEquals(before, storedIris(store), "no datatype of the failed seeding was committed");
	}

	/**
	 * Exact reference counts make seeding create the missing datatypes through the startup writer: all 48 then exist,
	 * equal to an independent scan, the created ones numbered in seeding order, and the next open finds the same ids.
	 */
	@Test
	void trustedCountsSeedingCreatesTheMissingDatatypesInSeedingOrder() throws Exception {
		LmdbStoreConfig exact = config().setLegacyReferenceCountRepairEnabled(true);
		Path store = legacyStoreWithTrustedCounts(exact);
		Map<String, List<StoredIri>> before = storedIris(store);

		Map<String, Long> first = seededIds(store, exact);
		Map<String, List<StoredIri>> scanned = storedIris(store);
		long previous = Long.MIN_VALUE;
		for (CoreDatatype datatype : coreDatatypes()) {
			String iri = datatype.getIri().stringValue();
			List<StoredIri> records = scanned.getOrDefault(iri, List.of());
			assertEquals(1, records.size(), () -> iri + " exists once after seeding: " + records);
			assertEquals(records.get(0).id(), first.get(iri), iri + ": seeded id equals the stored record");
			if (!before.containsKey(iri)) {
				long id = first.get(iri);
				assertTrue(id > previous, () -> iri + " was created after the datatypes seeded before it");
				previous = id;
			}
		}
		assertTrue(before.size() < scanned.size(), "fixture: seeding created missing datatypes");
		System.out.println("TRUSTED-SEEDED-DATATYPE-IDS first " + first);
		Map<String, Long> second = seededIds(store, exact);
		System.out.println("TRUSTED-SEEDED-DATATYPE-IDS second " + second);
		assertEquals(first, second, "the next open finds exactly the created ids");
	}

	private static Map<String, Long> seededIds(Path store, LmdbStoreConfig config) throws IOException {
		Map<String, Long> ids = new TreeMap<>();
		SailRepository repository = new SailRepository(new LmdbStore(store.toFile(), config));
		try {
			repository.init();
			ValueStore values = ((LmdbStore) repository.getSail()).getBackingStore().valueStore();
			assertTrue(values.hasTrustedReferenceCounts(), "fixture: seeding may create datatypes");
			for (CoreDatatype datatype : coreDatatypes()) {
				ids.put(datatype.getIri().stringValue(), values.getId(datatype.getIri()));
			}
		} finally {
			repository.shutDown();
		}
		return ids;
	}

	enum Image {
		/** 6.1.0's store, first opened by this build: the XSD namespace is absent, rdf:langString present. */
		WRITTEN_BY_6_1_0,
		/** The same store after this build wrote plain literals: xsd:string and its namespace exist. */
		SECOND_OPEN,
		/** As SECOND_OPEN, plus xsd:gYear stored only under the caller-supplied namespace "http://www.w3.org/2001/". */
		ALTERNATIVE_SPLIT,
		/** 6.1.0's store plus only that gYear split: the XSD namespace itself is absent, so no primary lookup runs. */
		ALTERNATIVE_SPLIT_WITHOUT_NAMESPACE
	}

	@ParameterizedTest
	@EnumSource(Image.class)
	void seededDatatypeIdsEqualAnIndependentScanOfTheStoredIris(Image image) throws Exception {
		Path store = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", store);
		boolean alternativeSplit = image == Image.ALTERNATIVE_SPLIT
				|| image == Image.ALTERNATIVE_SPLIT_WITHOUT_NAMESPACE;
		if (image != Image.WRITTEN_BY_6_1_0) {
			write(store, connection -> {
				connection.begin();
				if (image != Image.ALTERNATIVE_SPLIT_WITHOUT_NAMESPACE) {
					connection.add(VF.createIRI("urn:seed:s"), VF.createIRI("urn:seed:p"), VF.createLiteral("plain"));
				}
				if (alternativeSplit) {
					connection.add(VF.createIRI("urn:seed:s"), VF.createIRI("urn:seed:p"),
							VF.createIRI("http://www.w3.org/2001/", "XMLSchema#gYear"));
				}
				connection.commit();
			});
		}
		Map<String, List<StoredIri>> stored = storedIris(store);
		if (alternativeSplit) {
			List<StoredIri> gYear = stored.get(XSD + "gYear");
			assertEquals(1, gYear.size(), () -> "fixture: one gYear record " + gYear);
			assertEquals("http://www.w3.org/2001/", gYear.get(0).namespace(),
					"fixture: gYear exists only under its alternative namespace split");
			boolean canonicalNamespace = stored.values()
					.stream()
					.flatMap(List::stream)
					.anyMatch(record -> record.namespace().equals(XSD));
			assertEquals(image == Image.ALTERNATIVE_SPLIT, canonicalNamespace,
					"fixture: whether the canonical XSD namespace exists, i.e. whether the primary lookup runs");
		}

		Map<String, Long> seeded = new TreeMap<>();
		Map<String, Long> scanned = new TreeMap<>();
		SailRepository repository = new SailRepository(new LmdbStore(store.toFile(), config()));
		try {
			repository.init();
			ValueStore values = ((LmdbStore) repository.getSail()).getBackingStore().valueStore();
			assertFalse(values.hasTrustedReferenceCounts(), "fixture: seeding only looks datatypes up");
			for (CoreDatatype datatype : coreDatatypes()) {
				IRI iri = datatype.getIri();
				// the seeding pass cached its answer for exactly this IRI
				seeded.put(iri.stringValue(), values.getId(iri));
				List<StoredIri> records = stored.getOrDefault(iri.stringValue(), List.of());
				assertTrue(records.size() <= 1, () -> "fixture: at most one record per datatype " + records);
				scanned.put(iri.stringValue(), records.isEmpty() ? LmdbValue.UNKNOWN_ID : records.get(0).id());
			}
		} finally {
			repository.shutDown();
		}
		System.out.println("SEEDED-DATATYPE-IDS " + image + " " + seeded);
		assertEquals(scanned, seeded, image + ": seeded datatype ids equal the stored IRI records");
		if (alternativeSplit) {
			assertTrue(seeded.get(XSD + "gYear") != LmdbValue.UNKNOWN_ID, "the alternative split is found");
		}
	}

