	private Path legacyStoreWrittenByThisBuild() throws Exception {
		Path store = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", store);
		write(store, connection -> {
			connection.begin();
			for (int i = 0; i < 10; i++) {
				connection.add(VF.createIRI("urn:seed:s" + i), VF.createIRI("urn:seed:p"),
						VF.createLiteral("plain " + i));
			}
			connection.commit();
		});
		return store;
	}

	/** 6.1.0's store, opened once by this build and then given exact reference counts offline. */
	private Path legacyStoreWithTrustedCounts(LmdbStoreConfig exact) throws Exception {
		Path store = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", store);
		write(store, exact, connection -> {
		});
		LmdbStore.reconstructReferenceCountsOffline(store.toFile(), exact);
		return store;
	}

	private static boolean causes(Throwable failure, String message) {
		for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
			if (message.equals(cause.getMessage())) {
				return true;
			}
		}
		return false;
	}

	private static void write(Path store, Work work) {
		write(store, config(), work);
	}

	private static void write(Path store, LmdbStoreConfig config, Work work) {
		SailRepository repository = new SailRepository(new LmdbStore(store.toFile(), config));
		try (RepositoryConnection connection = repository.getConnection()) {
			work.run(connection);
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setInlineLiterals(false);
	}

	private static List<CoreDatatype> coreDatatypes() {
		List<CoreDatatype> datatypes = new ArrayList<>(List.of(CoreDatatype.XSD.values()));
		datatypes.add(CoreDatatype.RDF.LANGSTRING);
		return datatypes;
	}

	/** Counts native reads on this thread made by the core-datatype seeding pass only. */
	private static MockedStatic<LMDB> seedingCounter(int[] reads) {
		int[] depth = new int[1];
		return mockStatic(LMDB.class, invocation -> {
			boolean outermost = depth[0]++ == 0;
			try {
				if (outermost && READS.contains(invocation.getMethod().getName())) {
					for (StackTraceElement frame : new Throwable().getStackTrace()) {
						if (frame.getMethodName().equals("seedCoreDatatypes")) {
							reads[0]++;
							break;
						}
					}
				}
				return invocation.callRealMethod();
			} finally {
				depth[0]--;
			}
		});
	}

	/** Counts dictionary record reads (point and cursor) on this thread. */
	private static MockedStatic<LMDB> dictionaryReadCounter(int[] reads) {
		int[] depth = new int[1];
		return mockStatic(LMDB.class, invocation -> {
			boolean outermost = depth[0]++ == 0;
			try {
				String name = invocation.getMethod().getName();
				if (outermost && (name.equals("mdb_get") || name.equals("mdb_cursor_get"))) {
					reads[0]++;
				}
				return invocation.callRealMethod();
			} finally {
				depth[0]--;
			}
		});
	}

	/** Lexical IRI to its stored records, decoded from the closed value environment without the ValueStore. */
	private static Map<String, List<StoredIri>> storedIris(Path store) throws IOException {
		Map<Long, byte[]> records = new LinkedHashMap<>();
		long env = NULL;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			env = handle.get(0);
			E(mdb_env_set_maxdbs(env, 64));
			E(mdb_env_open(env, store.resolve("values").toString(), MDB_NOTLS | MDB_RDONLY, 0664));
			LmdbUtil.readTransaction(env, (inner, txn) -> {
				var database = inner.mallocInt(1);
				E(mdb_dbi_open(txn, (String) null, 0, database));
				PointerBuffer cursorHandle = inner.mallocPointer(1);
				E(mdb_cursor_open(txn, database.get(0), cursorHandle));
				long cursor = cursorHandle.get(0);
				try {
					MDBVal key = MDBVal.calloc(inner).mv_data(inner.bytes(new byte[] { 5 }));
					MDBVal value = MDBVal.calloc(inner);
					for (int rc = mdb_cursor_get(cursor, key, value, MDB_SET_RANGE); rc == MDB_SUCCESS
							&& key.mv_data().get(key.mv_data().position()) == 5; rc = mdb_cursor_get(cursor, key, value,
									MDB_NEXT)) {
						ByteBuffer idKey = key.mv_data().duplicate();
						idKey.get();
						long id = Varint.readUnsigned(idKey);
						byte[] bytes = new byte[value.mv_data().remaining()];
						value.mv_data().duplicate().get(bytes);
						records.put(id, bytes);
					}
				} finally {
					mdb_cursor_close(cursor);
				}
				return null;
			});
		} finally {
			if (env != NULL) {
				mdb_env_close(env);
			}
		}
		Map<String, List<StoredIri>> iris = new LinkedHashMap<>();
		for (Map.Entry<Long, byte[]> record : records.entrySet()) {
			byte[] bytes = record.getValue();
			if (bytes.length == 0 || bytes[0] != 0) {
				continue; // not an IRI record
			}
			ByteBuffer encoded = ByteBuffer.wrap(bytes);
			encoded.get();
			long namespaceId = Varint.readUnsigned(encoded);
			byte[] namespaceRecord = records.get(namespaceId);
			if (namespaceRecord == null || namespaceRecord.length == 0 || namespaceRecord[0] != 4) {
				continue; // a retired payload without its namespace
			}
			String namespace = new String(namespaceRecord, 1, namespaceRecord.length - 1, StandardCharsets.UTF_8);
			String localName = new String(bytes, encoded.position(), encoded.remaining(), StandardCharsets.UTF_8);
			iris.computeIfAbsent(namespace + localName, ignored -> new ArrayList<>())
					.add(new StoredIri(record.getKey(), namespace));
		}
		return iris;
	}
